}

draw((0,-3)--(0,3),red);
draw((1,-3)--(1,3),red);
draw((-3,-4/3)--(3,8/3),red);
draw((-3,0)--(3,0),blue);
draw(graph(upperhyper,-1.863,2.863),blue);
draw(graph(lowerhyper,-1.836,2.863),blue);

